sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    console.log(event,event.payload);
    console.log(event.payload.item.link);
    var event = event.payload.item ;
    // Check if event contains an 'id' and if it includes the word 'document'
    if (event.id && event.id.includes('document')) {
        // Assuming there's a corresponding link in event.url, you can redirect to it
        if (event.link) {
            helpers.navigate.to(null, null, null, null, null, null, {
                url: event.link
            });
        } else {
            console.log('No link found, no redirection.');
        }
    } else {
        console.log('No redirection needed for this event.');
    }
}
